import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.PrintWriter;

public class Solution implements Runnable {
    private final BufferedReader inf;
    private final PrintWriter ouf;

    public Solution(BufferedReader inf, PrintWriter ouf) {
        this.inf = inf;
        this.ouf = ouf;
    }

    public Solution() {
        this(new BufferedReader(new InputStreamReader(System.in)), new PrintWriter(System.out));
    }

    private static int[] readIntList(BufferedReader br) {
        String[] parts = br.readLine().split(" ");
        int[] list = new int[parts.length];
        for (int i = 0; i < parts.length; i++) {
            list[i] = Integer.parseInt(parts[i]);
        }
        return list;
    }

    private static long[] readLongList(BufferedReader br) {
        String[] parts = br.readLine().split(" ");
        long[] list = new long[parts.length];
        for (int i = 0; i < parts.length; i++) {
            list[i] = Long.parseLong(parts[i]);
        }
        return list;
    }

    public void solve() {
        String s = inf.readLine();
        String[] tokens = inf.readLine().split(" ");
        boolean found = false;
        for (String token : tokens) {
            if (s.charAt(0) == token.charAt(0) || s.charAt(1) == token.charAt(1)) {
                found = true;
                break;
            }
        }
        ouf.println(found ? "YES" : "NO");
    }

    @Override
    public void run() {
        solve();
        ouf.close();
    }

    public static void main(String[] args) {
        Thread thread = new Thread(null, new Solution(), "name", 1 << 27);
        thread.start();
    }
}

